(42111, 'Genesis 36:19', 'Genesis', 36, 19, 'دا ټولې قبیلې د عیسو د اولادې څخه وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_19.mp3', '', 1761754199, 1761754199),
(42112, 'Genesis 36:20', 'Genesis', 36, 20, 'دا د سعیر حوري زامن وو چې په هغې سیمه کې اوسېدل: لوتان، شوبال، صبعون، عنه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_20.mp3', '', 1761754199, 1761754199),
(42113, 'Genesis 36:21', 'Genesis', 36, 21, 'دیشون، ایصر او دیشان. دا په ادوم کې د سعیر زامن او د حوریانو مشران وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_21.mp3', '', 1761754199, 1761754199),
(42114, 'Genesis 36:22', 'Genesis', 36, 22, 'د لوتان زامن: حوري او هومام. (تمناع د لوتان خور وه.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_22.mp3', '', 1761754199, 1761754199),
(42115, 'Genesis 36:23', 'Genesis', 36, 23, 'د شوبال زامن: علوان، مناحت، عیبال، شفو او اونام.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_23.mp3', '', 1761754199, 1761754199),
(42116, 'Genesis 36:24', 'Genesis', 36, 24, 'د صبعون زامن: ایه او عنه. (دا هماغه عنه دی، کله چې هغه د خپل پلار صبعون خره څرول، نو په دښته کې یې د تودو اوبو چینې وموندلې.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_24.mp3', '', 1761754199, 1761754199),
(42117, 'Genesis 36:25', 'Genesis', 36, 25, 'د عنه اولادونه: دیشون او اهولیبامه د عنه لور.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_25.mp3', '', 1761754199, 1761754199),
(42118, 'Genesis 36:26', 'Genesis', 36, 26, 'د دیشون زامن: حمدان، اشبان، یتران او کران.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_26.mp3', '', 1761754199, 1761754199),
(42119, 'Genesis 36:27', 'Genesis', 36, 27, 'د ایصر زامن: بلهان، زعوان او عقان.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_27.mp3', '', 1761754199, 1761754199),
(42120, 'Genesis 36:28', 'Genesis', 36, 28, 'د دیشان زامن: عوص او اران.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_28.mp3', '', 1761754199, 1761754199),
(42121, 'Genesis 36:29', 'Genesis', 36, 29, 'دا د حوریانو مشران وو: لوتان، شوبال، صبعون، عنه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_29.mp3', '', 1761754199, 1761754199),
(42122, 'Genesis 36:30', 'Genesis', 36, 30, 'دیشون، ایصر او دیشان. دا د حوریانو قبیلې وې چې د ادوم په خاوره کې اوسېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_30.mp3', '', 1761754199, 1761754199),
(42123, 'Nehemiah 2:1', 'Nehemiah', 2, 1, 'د ارتخششتا د پاچاهۍ په شلم کال د نیسان په میاشت کې یوه ورځ کله چې ارتخششتا پاچا ته شراب راوړل شول، ما هغه ته د شرابو جام وړاندې کړ. هغه هېڅکله زه خفه لیدلی نه وم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_1.mp3', '', 1761754199, 1761754199),
(42124, 'Nehemiah 2:2', 'Nehemiah', 2, 2, 'نو هغه زما څخه پوښتنه وکړه: «ولې داسې خفه ښکارې؟ فکر نه کوم چې ته ناروغ یې، نو هرومرو ته خفه یې.» زه د دې پوښتنې څخه ډېر ووېرېدم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_2.mp3', '', 1761754199, 1761754199),
(42125, 'Nehemiah 2:3', 'Nehemiah', 2, 3, 'او ځواب مې ورکړ: «تاسو اعلیحضرت دې تل ژوندی اوسئ! زه به څنګه خفه ښکاره نه شم؟ هغه ښار چې زما نیکونه په کې ښخ دي هغه وران شوی دی او د هغه دروازې سوځېدلې دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_3.mp3', '', 1761754199, 1761754199),
(42126, 'Nehemiah 2:4', 'Nehemiah', 2, 4, 'پاچا پوښتنه وکړه: «ته څه غواړې؟» ما د اسمانونو خدای ته دعا وکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_4.mp3', '', 1761754199, 1761754199),
(42127, 'Nehemiah 2:5', 'Nehemiah', 2, 5, 'او بیا مې پاچا ته ځواب ورکړ: «که چېرې تاسو اعلیحضرت زما څخه خوشحاله او راضي یئ چې زما غوښتنه ومنئ، نو ما ولېږئ چې یهودا ته لاړ شم، یعنې هغه ښار ته چې زما نیکونه په کې ښخ دي، ترڅو هغه ښار بېرته ودان کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_5.mp3', '', 1761754199, 1761754199),
(42128, 'Nehemiah 2:6', 'Nehemiah', 2, 6, 'پاچا چې ملکه یې په څنګ کې ناسته وه، پوښتنه وکړه: «ته د څومره وخت دپاره ځې او کله بېرته راځې؟» ما هغه ته د راستنېدلو وخت وښود او بیا هغه زما غوښتنه ومنله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_6.mp3', '', 1761754199, 1761754199),
(42129, 'Nehemiah 2:7', 'Nehemiah', 2, 7, 'بیا ما پاچا ته وویل: «اعلیحضرته! که ستاسو خوښه وي، نو ماته د فرات د سیند د لوېدیځې خوا د سیمو په والیانو باندې لیکونه راکړئ، ترڅو وکولای شم چې یهودا ته په خیریت سره لاړ شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_7.mp3', '', 1761754199, 1761754199),
(42130, 'Nehemiah 2:8', 'Nehemiah', 2, 8, 'همدارنګه ما د هغه څخه وغوښتل چې د شاهي ځنګلونو ساتونکي اساف ته هم یو لیک راکړي او هغه ته لارښوونه وکړي چې ماته د هغې کلا د دروازو د جوړولو دپاره چې د خدای د کور په څنګ کې ده، د ښار د دېوالونو دپاره او د هغه کور د جوړولو دپاره چې زه به په کې اوسېږم، لرګي راکړي. هغه ټول شیان چې ما غوښتي وو پاچا هغه ماته راکړل، ځکه چې زما خدای په ما باندې مهربانه او زما سره مل ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_8.mp3', '', 1761754199, 1761754199),
(42131, 'Nehemiah 2:9', 'Nehemiah', 2, 9, 'پاچا څو عسکري منصبداران او د سپرو عسکرو یو لښکر زما سره ولېږه او ما د فرات د سیند لوېدیځې خواته سفر وکړ. هلته مې والیانو ته د پاچا لیکونه ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_9.mp3', '', 1761754199, 1761754199),
(42132, 'Nehemiah 2:10', 'Nehemiah', 2, 10, 'خو کله چې سنبلط چې د بیت حورون د ښارګوټي اوسېدونکی او طوبیا چې د عمون د ولایت یو مامور ؤ دا واورېدل چې یو څوک راغلی دی، ترڅو د اسراییلو د خلکو د ښېګڼې دپاره کار وکړي، نو هغوی ډېر خفه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_10.mp3', '', 1761754199, 1761754199),
(42133, 'Nehemiah 2:11', 'Nehemiah', 2, 11, 'زه اورشلیم ته لاړم او تر درې ورځو پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_11.mp3', '', 1761754199, 1761754199),
(42134, 'Nehemiah 2:12', 'Nehemiah', 2, 12, 'ما هېچا ته د هغه پلان په اړه ونه ویل چې زما خدای د اورشلیم په هکله زما په زړه کې جوړ کړی ؤ. بیا زه د شپې راپاڅېدم، راووتم او د خپلو ملګرو څخه مې څو تنه د ځان سره بوتلل. هلته یوازې یو خر ؤ چې زه ورباندې سپور وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_12.mp3', '', 1761754199, 1761754199),
(42135, 'Nehemiah 2:13', 'Nehemiah', 2, 13, 'زه د درې د دروازې له لارې د ښار نه ووتلم، د ښامار د چینې څخه تېر شوم او د خزلو د دروازې خواته لاړم. د تګ په وخت کې مې د نژدې څخه د ښار غورځېدلي دېوالونه او سوځول شوې دروازې په غور سره ولیدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_13.mp3', '', 1761754199, 1761754199),
(42136, 'Nehemiah 2:14', 'Nehemiah', 2, 14, 'زه د فوارې دروازې او د پاچا حوض ته ورسېدم. خو وروسته بیا لاره دومره بنده وه چې زما خر ورباندې تېرېدلی نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_14.mp3', '', 1761754199, 1761754199),
(42137, 'Nehemiah 2:15', 'Nehemiah', 2, 15, 'نو زه د قدرون درې ته ورښکته شوم او په لاره روان وم او دېوال ته مې کتل. بیا په هغه لاره باندې چې راغلی وم بېرته ستون شوم او د درې د دروازې له لارې بېرته ښار ته ورننوتلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_15.mp3', '', 1761754199, 1761754199),
(42138, 'Nehemiah 2:16', 'Nehemiah', 2, 16, 'د هغه ځای د مامورینو څخه هېڅوک پوه نه شو چې زه چېرته تللی وم او څه مې وکړل. ما نورو یهودیانو ته لکه کاهنانو، مشرانو، مامورینو او نورو هغو خلکو ته چې په دې کار کې به یې برخه اخیستله، تر هغه وخته هېڅ ونه ویل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_16.mp3', '', 1761754199, 1761754199),
(42139, 'Nehemiah 2:17', 'Nehemiah', 2, 17, 'خو هغوی ته مې وویل: «ګورئ چې مونږ د څه ډول کړاو سره مخامخ یو، ځکه چې اورشلیم وران شوی دی او د هغه دروازې سوځېدلې دي. راځئ چې د ښار دېوال بېرته جوړ کړو او خپل ځانونه د رسوایۍ څخه خلاص کړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_17.mp3', '', 1761754199, 1761754199),
(42140, 'Nehemiah 2:18', 'Nehemiah', 2, 18, 'بیا ما هغوی ته وویل چې خدای څنګه زما سره مل ؤ او مرسته یې راسره کوله او هغه څه مې هم ورته وویل چې پاچا راته ویلي وو. هغوی په ځواب کې وویل: «راځئ چې د بیا ودانولو په کار پیل وکړو.» نو هغوی په دې توګه دې ته تیار شول چې دا نېک کار پیل کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_18.mp3', '', 1761754199, 1761754199),
(42141, 'Nehemiah 2:19', 'Nehemiah', 2, 19, 'خو کله چې سنبلط، طوبیا او یو عرب چې جشم نومېده زمونږ د نقشې څخه خبر شول چې مونږ څه کوو، نو هغوی په مونږ باندې ملنډې ووهلې او زمونږ سپکاوی یې وکړ، ویې ویل: «تاسو څه کوئ؟ ایا غواړئ چې د پاچا په وړاندې سرکښي وکړئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_19.mp3', '', 1761754199, 1761754199),
(42142, 'Nehemiah 2:20', 'Nehemiah', 2, 20, 'ما ځواب ورکړ: «د اسمانونو خدای به مونږ ته بری راکړي. مونږ د هغه خدمتګاران یو او مونږ به د بیا ودانولو کار پیل کړو. خو تاسو نه د اورشلیم په چارو کې حق لرئ او نه د هغه په جایداد کې برخه لرئ او نه د هغه په دود او دستور او تاریخ کې شریک یئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah2_verse_20.mp3', '', 1761754199, 1761754199),
(42143, 'Judges 14:1', 'Judges', 14, 1, 'یوه ورځ شمشون تمنې ته لاړ او هلته یې یوه فلسطینۍ انجلۍ ولیدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_1.mp3', '', 1761754199, 1761754199),
(42144, 'Judges 14:2', 'Judges', 14, 2, 'کله چې هغه بېرته کور ته راستون شو، نو خپل مور او پلار ته یې وویل: «ما په تمنه کې یوه فلسطینۍ انجلۍ ولیدله. هغه ماته وکړئ، زه غواړم چې د هغې سره واده وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_2.mp3', '', 1761754199, 1761754199),
(42145, 'Judges 14:3', 'Judges', 14, 3, 'خو مور او پلار یې ورڅخه پوښتنه وکړه: «ایا ستا د قوم او خپلوانو په منځ کې انجلۍ نشته چې ته غواړې په هغو ناسنته فلسطینیانو کې ښځه وکړې؟» خو شمشون خپل پلار ته وویل: «همدا انجلۍ راته وکړئ. هغه زما خوښه ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_3.mp3', '', 1761754199, 1761754199),
(42146, 'Judges 14:4', 'Judges', 14, 4, 'د هغه مور او پلار نه پوهېدل چې دا کار د څښتن له خوا ؤ، ځکه چې څښتن یوه موقع کتله چې د فلسطینیانو په وړاندې کوم عمل وکړي. په هغه وخت کې فلسطینیانو په اسراییلو باندې حکومت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_4.mp3', '', 1761754199, 1761754199),
(42147, 'Judges 14:5', 'Judges', 14, 5, 'نو شمشون د خپل مور او پلار سره تمنې ته روان شو. کله چې هغه د تمنې د انګورو د باغونو څخه تېرېده، نو یو ځوان زمری راغی او په شمشون باندې وغورېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_5.mp3', '', 1761754199, 1761754199),
(42148, 'Judges 14:6', 'Judges', 14, 6, 'ناڅاپه د څښتن روح هغه قوي کړ او هغه په تشو لاسونو زمری دوه ټوټې کړ لکه یو سېرلی چې دوه ټوټې شي. خو هغه خپل مور او پلار ته په دې هکله څه ونه ویل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_6.mp3', '', 1761754199, 1761754199),
(42149, 'Judges 14:7', 'Judges', 14, 7, 'بیا هغه لاړ او د هغې انجلۍ سره یې خبرې وکړې او هغه یې خوښه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_7.mp3', '', 1761754199, 1761754199),
(42150, 'Judges 14:8', 'Judges', 14, 8, 'څه موده وروسته کله چې شمشون د هغې سره د واده کولو دپاره بېرته روان شو، هغه د لارې څخه راوګرځېد چې د هغه زمري مړی وویني چې وژلی یې ؤ. هغه زمري ته وکتل او حیران شو چې د هغه په بدن کې ډېرې د شاتو مچۍ او شات وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_8.mp3', '', 1761754199, 1761754199),
(42151, 'Judges 14:9', 'Judges', 14, 9, 'هغه په خپلو لاسونو یو څه شات راوتوږل او په لاره کې یې وخوړل. بیا هغه خپل مور او پلار ته ورغی او هغوی ته یې هم لږ ورکړل او هغوی وخوړل. خو شمشون هغوی ته ونه ویل چې دا شات یې د مړ زمري د بدن څخه راخیستي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_9.mp3', '', 1761754199, 1761754199),
(42152, 'Judges 14:10', 'Judges', 14, 10, 'د هغه پلار د واده دپاره تیاری نیوه چې شمشون هلته په تمنه کې یوه مېلمستیا چې په هغې زمانه کې د ځوانانو ترمنځ رواج ؤ، جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_10.mp3', '', 1761754199, 1761754199),
(42153, 'Judges 14:11', 'Judges', 14, 11, 'کله چې فلسطینیانو ولیدل چې شمشون څه ډول سړی دی، نو هغوی خپلو دېرشو ځوانانو ته وویل چې د هغه سره په مېلمستیا کې پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_11.mp3', '', 1761754199, 1761754199),
(42154, 'Judges 14:12', 'Judges', 14, 12, 'شمشون هغوی ته وویل: «اجازه راکړئ چې تاسو ته یوه معما ووایم. که چېرې تاسو ماته د مېلمستیا په اووه ورځو کې د هغې ځواب راکړ، زه به تاسو ته د کتان دېرش جوړې ساده کالي او دېرش جوړې ښکلي کالي درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_12.mp3', '', 1761754199, 1761754199),
(42155, 'Judges 14:13', 'Judges', 14, 13, 'خو که چېرې تاسو ځواب رانه کړ، تاسو باید ماته دېرش جوړه د کتان ساده کالي او دېرش جوړه ښکلي کالي راکړئ.» هغوی ورته وویل: «ته خپله معما مونږ ته ووایه چې مونږ یې واورو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_13.mp3', '', 1761754199, 1761754199),
(42156, 'Judges 14:14', 'Judges', 14, 14, 'هغه وویل: د خوړونکي څخه راووت د خوړلو شی د زورور څخه راووت یو خوږ شی درې ورځې وروسته بیاهم هغوی ونه شو کولای چې د معما ځواب پیدا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_14.mp3', '', 1761754199, 1761754199),
(42157, 'Judges 14:15', 'Judges', 14, 15, 'په څلورمه ورځ هغوی د شمشون ښځې ته وویل: «ته خپل مېړه وغولوه چې مونږ ته د دې معما معنی ووایي او که نه، نو مونږ به تا او ستا د پلار کورنۍ وسوځوو. ایا تاسو مونږ دلته د دې دپاره راغوښتي یو چې لوټ مو کړئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_15.mp3', '', 1761754199, 1761754199),
(42158, 'Judges 14:16', 'Judges', 14, 16, 'بیا د شمشون ښځه خپل مېړه ته په ژړا ورغله او ویې ویل: «زه درباندې ګرانه نه یم! ته زما څخه کرکه کوې. تا زما وطندارانو ته یوه معما ویلې ده، خو د هغې معنی دې ماته نه ده ویلې!» شمشون وویل: «ما حتی خپل مور او پلار ته هم نه دي ویلي، نو تاته یې ولې ووایم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_16.mp3', '', 1761754199, 1761754199),
(42159, 'Judges 14:17', 'Judges', 14, 17, 'هغې د مېلمستیا په ټولو اوو ورځو کې وژړل. خو په اوومه ورځ هغه ورته د معما معنی وویله، ځکه چې هغه یې ډېر تنګ کړ. بیا هغې د معما ځواب هغو ځوانانو ته ووایه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_17.mp3', '', 1761754199, 1761754199),
(42160, 'Judges 14:18', 'Judges', 14, 18, 'په اوومه ورځ د لمر پرېواته څخه مخکې د ښارګوټي خلک هغه ته راغلل او ویې ویل: څه شی به خوږ وي ډېر د شاتو څخه؟ څه شی قوي به وي ډېر د زمري څخه؟ شمشون ځواب ورکړ: زما په غوا باندې که تاسو قلبه کړې نه وای نو دا معما به مو حل کړې نه وای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_18.mp3', '', 1761754199, 1761754199),
(42161, 'Judges 14:19', 'Judges', 14, 19, 'ناڅاپه د څښتن روح هغه قوي کړ او هغه د اشقلون ښار ته لاړ او د هغه ځای دېرش کسان یې ووژل. هغوی یې لوڅ کړل او د هغوی جامې یې هغو خلکو ته ورکړې چې معما یې حل کړې وه. بیا هغه ډېر په قهر سره بېرته د خپل پلار کور ته لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_19.mp3', '', 1761754199, 1761754199),
(42162, 'Judges 14:20', 'Judges', 14, 20, 'او د شمشون ښځه د هغه ملګري ته چې په واده کې یې د هغه خدمت کاوه، واده شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges14_verse_20.mp3', '', 1761754199, 1761754199),
(42163, 'Isaiah 61:1', 'Isaiah', 61, 1, 'نازل شوی دی په ما روح د څښتن تعالی ځکه چې زه یې مسح کړی یمه ترڅو ورسوم زېری غریبانو ته زه رالېږلی یم هغه چې ورکړم شفا مات شویو زړونو ته او اسیرانو او بندیانو ته اعلان کړم ازادي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_1.mp3', '', 1761754199, 1761754199),
(42164, 'Isaiah 61:2', 'Isaiah', 61, 2, 'زه یې رالېږلی یمه چې کړم اعلان د مهربانۍ کال د څښتن او دا چې رارسېدلې ده د انتقام ورځ د څښتن زه یې رالېږلی یمه چې تسلي ورکړم ټولو ویرجنو خلکو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_2.mp3', '', 1761754199, 1761754199),
(42165, 'Isaiah 61:3', 'Isaiah', 61, 3, 'هغو خلکو ته چې ویر کوي صهیون کې د ایرو په ځای به ورکړمه هغوی ته ښایسته تاج د ویر په ځای به خوشحالي ورکړمه او خفګان به یې بدل شي د ستاینې په سندره هغوی به وي خپلې نېکۍ کې د څېړیو د ونو په شان چې کرلي دي څښتن د خپل جلال دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_3.mp3', '', 1761754199, 1761754199),
(42166, 'Isaiah 61:4', 'Isaiah', 61, 4, 'هغوی به بیا جوړ کړي هغه پخواني ښارونه چې د ډېر وخت دپاره وران پراته وو هغوی به بیا ودان کړي هغه وران ښارونه چې په کې ژوند نه کاوه د خلکو ډېرو نسلونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_4.mp3', '', 1761754199, 1761754199),
(42167, 'Isaiah 61:5', 'Isaiah', 61, 5, 'پردي خلک به کوي پام ستاسو رمو باندې هغوی به ستاسو بزګران وي او وي باغوانان به د انګورو د باغونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_5.mp3', '', 1761754199, 1761754199),
(42168, 'Isaiah 61:6', 'Isaiah', 61, 6, 'خو د څښتن د کاهنانو په نامه به مشهور شئ تاسو خلک به وایي چې یئ د خدای خادمان تاسو به شئ برخمن د نورو قومونو له شتمنیو څخه او تاسو به ویاړئ چې هغه شتمني شوه ستاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_6.mp3', '', 1761754199, 1761754199),
(42169, 'Isaiah 61:7', 'Isaiah', 61, 7, 'پای ته به ورسیږي سپکاوی او رسوایي ستاسو او وبه اوسېږئ په خپل هېواد کې شي به دوه چنده شتمني ستاسو او خوشحالي به مو په برخه شي د تل دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_7.mp3', '', 1761754199, 1761754199),
(42170, 'Isaiah 61:8', 'Isaiah', 61, 8, 'څښتن وایي: «زه انصاف خوښوم او کوم کرکه له غلا او ظلمه په وفادارۍ سره به ورکړم اجر خپلو خلکو ته او د هغوی سره به وکړم یو تلپاتې لوظ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_8.mp3', '', 1761754199, 1761754199),
(42171, 'Isaiah 61:9', 'Isaiah', 61, 9, 'ټولو قومونو او هېوادونو کې به شي مشهوره اولاده د هغوی هرڅوک چې وویني هغوی، نو په دې به پوه شي چې ما ورکړی برکت هغوی ته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_9.mp3', '', 1761754199, 1761754199),
(42172, 'Isaiah 61:10', 'Isaiah', 61, 10, 'زه خوشحالي کومه ډېره د څښتن په خاطر زما ځان به خوشحالي کړي په ستاینه د څښتن ځکه هغه راته اغوستي د ژغورنې کالي او د عدالت چپنه لکه چې څنګه ښایسته کیږي زوم لونګۍ باندې او ناوې ګاڼو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_10.mp3', '', 1761754199, 1761754199),
(42173, 'Isaiah 61:11', 'Isaiah', 61, 11, 'لکه چې څنګه راشنه کوي تخم ځمکه او راشنه کوي باغ کرل شوي نیالګي همدارنګه څښتن تعالی به کړي ښکاره خپل عدالت ټولو قومونو لره او هغوی به وکړي د هغه ستاینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah61_verse_11.mp3', '', 1761754199, 1761754199),
(42174, 'Isaiah 56:1', 'Isaiah', 56, 1, 'څښتن خپل قوم ته داسې وایي: «د انصاف او عدالت په بنیاد چلند وکړئ، ځکه چې زه به زر راشم، تاسو ته به خلاصون درکړم او زما عدالت به څرګند شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_1.mp3', '', 1761754199, 1761754199),
(42175, 'Isaiah 56:2', 'Isaiah', 56, 2, 'بختور دی هغه څوک چې تل داسې کوي او د سبت د ورځې درناوی کوي او د هغه سپکاوی نه کوي. له بدو کړنو ځان ساتي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_2.mp3', '', 1761754199, 1761754199),
(42176, 'Isaiah 56:3', 'Isaiah', 56, 3, 'د پردي وطن سړی چې د څښتن د قوم سره یوځای شوی، هغه دې فکر ونه کړي چې څښتن به خامخا ما له خپلو خلکو نه بېل کړي او نه دې خصي سړی دا فکر وکړي چې زه خو د وچې ونې په شان بې حاصله یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_3.mp3', '', 1761754199, 1761754199),
(42177, 'Isaiah 56:4', 'Isaiah', 56, 4, 'ځکه څښتن داسې وایي: «کوم خصیان چې زما د سبت د ورځې درناوی وکړي، هغه کار وکړي چې زه ورباندې خوشحالېږم او په وفادارۍ سره زما په لوظ باندې ټینګ ولاړ وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_4.mp3', '', 1761754199, 1761754199),
(42178, 'Isaiah 56:5', 'Isaiah', 56, 5, 'نو بیا هر خصي ته به د خپل کور په دېوالونو کې یو یادګار او یو نوم ورکړم. د هغه چا په پرتله چې اولادونه لري، نوم به یې لوړ وي او تل ترتله به یادیږي، هېڅکله به هغه هېر نه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_5.mp3', '', 1761754199, 1761754199),
(42179, 'Isaiah 56:6', 'Isaiah', 56, 6, 'نو څښتن هغو پردیو خلکو ته چې د هغه د قوم سره یوځای کیږي، د هغه د نوم سره مینه کوي، د هغه خدمت کوي، د سبت د ورځې درناوی کوي او د دې ورځې سپکاوی نه کوي، بلکې په وفادارۍ سره د هغه په لوظ باندې ټینګ ولاړ وي، وایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_6.mp3', '', 1761754199, 1761754199),
(42180, 'Isaiah 56:7', 'Isaiah', 56, 7, '«تاسو به خپل سپېڅلي غره ته راولم او هلته به په خپل کور کې چې د دعا کولو ځای دی خوشحالي درکړم. کومې سوځېدونکې نذرانې او نورې قربانۍ چې تاسو یې زما د قربانۍ په ځای باندې کوئ، هغه به قبولې کړم. ځکه زما کور به د ټولو قومونو دپاره د دعا د کور په نوم وبلل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_7.mp3', '', 1761754199, 1761754199),
(42181, 'Isaiah 56:8', 'Isaiah', 56, 8, 'څښتن تعالی چې خپل قوم اسراییل یې له جلاوطنۍ نه خپل وطن ته راوستلی دی، وعده کړې ده چې هغه به نور خلک هم راولي چې د دوی سره یوځای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_8.mp3', '', 1761754199, 1761754199),
(42182, 'Isaiah 56:9', 'Isaiah', 56, 9, 'ای ټولو وحشي او د ځنګل داړونکو حیواناتو راشئ، دا خلک وداړئ او ویې خورئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_9.mp3', '', 1761754199, 1761754199),
(42183, 'Isaiah 56:10', 'Isaiah', 56, 10, 'څښتن وایي: «زما د قوم مشران د هغو پهره دارانو په شان دي چې ړانده وي او په خطر نه پوهیږي. دا مشران د هغو ساتونکو سپیو په شان دي چې نه غاپي، هسې پراته وي او خوبونه ویني. خوب یې څومره خوښ دی!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_10.mp3', '', 1761754199, 1761754199),
(42184, 'Isaiah 56:11', 'Isaiah', 56, 11, 'هغوی د حریصو سپیو په شان دي چې هېڅکله نه مړیږي او هم د هغو شپنو په شان دي چې په خطر نه پوهیږي. هر یو یې هغه کار کوي چې زړه یې غواړي، یوازې خپلې ګټې په پام کې نیسي او بس.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_11.mp3', '', 1761754199, 1761754199),
(42185, 'Isaiah 56:12', 'Isaiah', 56, 12, 'هغوی وایي: ‹راځئ چې شراب واخلو او هرڅومره چې کولای شو ویې څښو! سبا ورځ به د نن ورځې څخه هم بهتره وي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah56_verse_12.mp3', '', 1761754199, 1761754199),
(42186, 'Job 33:1', 'Job', 33, 1, 'نو اے ايُوبه، زما خبرې واوره، او زۀ چې څۀ وايم نو هغې ته متوجو شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_1.mp3', '', 1761754199, 1761754199),
(42187, 'Job 33:2', 'Job', 33, 2, 'نو اوس چې ما خبرې شروع کړې، نو پرېږده چې زړۀ تش کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_2.mp3', '', 1761754199, 1761754199),
(42188, 'Job 33:3', 'Job', 33, 3, 'زما ټولې خبرې سپينې دى، او زۀ رښتيا رښتيا وايم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_3.mp3', '', 1761754199, 1761754199),
(42189, 'Job 33:4', 'Job', 33, 4, 'د خُدائ پاک روح زۀ جوړ کړے يم، او د قادر خُدائ ساه ما له ژوند راکړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_4.mp3', '', 1761754199, 1761754199),
(42190, 'Job 33:5', 'Job', 33, 5, 'کۀ تا سره څۀ جواب وى نو ما له يې راکړه، د خبرې دپاره ځان تيار کړه او په هغې ټينګ ودرېږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_5.mp3', '', 1761754199, 1761754199),
(42191, 'Job 33:6', 'Job', 33, 6, 'ګوره، زۀ هم د خُدائ پاک په نظر کښې ستا په شان يم، زۀ هم د خټې نه جوړ شوے وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_6.mp3', '', 1761754199, 1761754199),
(42192, 'Job 33:7', 'Job', 33, 7, 'نو زما نه مۀ يرېږه، او زۀ به تا سره زياتے نۀ کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_7.mp3', '', 1761754199, 1761754199),
(42193, 'Job 33:8', 'Job', 33, 8, 'تا زما په مخکښې خبرې کړې دى، او ما ستا ټولې خبرې اورېدلې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_8.mp3', '', 1761754199, 1761754199),
(42194, 'Job 33:9', 'Job', 33, 9, 'تۀ وائې چې، ”زۀ صفا او بې‌ګناه يم، زۀ معصُوم يم او په ما کښې هيڅ غلطى نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_9.mp3', '', 1761754199, 1761754199),
(42195, 'Job 33:10', 'Job', 33, 10, 'خو خُدائ پاک په ما کښې غلطى لټوى، هغه ما خپل دشمن ګڼى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_10.mp3', '', 1761754199, 1761754199),
(42196, 'Job 33:11', 'Job', 33, 11, 'هغه زما په پښو کښې زولنۍ اچوى، او زما په هر حرکت يې نظر دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_11.mp3', '', 1761754199, 1761754199),
(42197, 'Job 33:12', 'Job', 33, 12, 'خو په دې خبره کښې تۀ غلط يې. زۀ به تا ته ووايم چې ولې ځکه چې خُدائ پاک د انسان نه لوئ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_12.mp3', '', 1761754199, 1761754199),
(42198, 'Job 33:13', 'Job', 33, 13, 'تۀ په خُدائ پاک باندې اِلزام ولې لګوې، وائې چې هغه به زما د يوې خبرې جواب هم ونۀ کړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_13.mp3', '', 1761754199, 1761754199),
(42199, 'Job 33:14', 'Job', 33, 14, 'ځکه چې خُدائ پاک بار بار کلام کوى، خو خلق دې ته غوږ نۀ ږدى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_14.mp3', '', 1761754199, 1761754199),
(42200, 'Job 33:15', 'Job', 33, 15, 'کله چې بنى آدم په خوب اودۀ وى او هغه خوب وينى يا رويا وينى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_15.mp3', '', 1761754199, 1761754199),
(42201, 'Job 33:16', 'Job', 33, 16, 'نو خُدائ پاک به د هغوئ غوږونه کولاو کړى، او د خبردارى په ذريعه به هغوئ يروى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_16.mp3', '', 1761754199, 1761754199),
(42202, 'Job 33:17', 'Job', 33, 17, 'هغه يې د بدو عملونو نه راوګرځوى، او د غرور نه يې وساتى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_17.mp3', '', 1761754199, 1761754199),
(42203, 'Job 33:18', 'Job', 33, 18, 'هغه يې د مرګ نه بچ کوى، او د مرګ درياب د تېرېدو نه يې بچ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_18.mp3', '', 1761754199, 1761754199),
(42204, 'Job 33:19', 'Job', 33, 19, 'خُدائ پاک د بيمارۍ په ذريعه د خلقو اصلاح کوى، او د هغوئ په بدنونو باندې درد راولى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_19.mp3', '', 1761754199, 1761754199),
(42205, 'Job 33:20', 'Job', 33, 20, 'نو د هغوئ لوږه ختمه شى، او مزېدار خوراک ته يې هم زړۀ نۀ کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_20.mp3', '', 1761754199, 1761754199),
(42206, 'Job 33:21', 'Job', 33, 21, 'د هغوئ بدنونه ويلى شى، او دوه ګوتې مخ يې راوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_21.mp3', '', 1761754199, 1761754199),
(42207, 'Job 33:22', 'Job', 33, 22, 'هغوئ د مرګ په خولۀ ولاړ وى، او د مرګ فرښته د هغوئ انتظار کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_22.mp3', '', 1761754199, 1761754199),
(42208, 'Job 33:23', 'Job', 33, 23, 'خو کۀ د زرګونو فرښتو نه يوه فرښته راشى او چا ته صحيح لار وښائى نو دا بس دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_23.mp3', '', 1761754199, 1761754199),
(42209, 'Job 33:24', 'Job', 33, 24, 'او هغه په هغه کس باندې مِهربانه شى او ووائى چې، هغه بچ کړه چې قبر ته لاړ نۀ شى، ځکه چې ما ته د هغۀ د ژوند قيمت مِلاو شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_24.mp3', '', 1761754199, 1761754199),
(42210, 'Job 33:25', 'Job', 33, 25, 'د هغۀ بدن دې د ځوانۍ په وجه تازه شى، په هغۀ دې د ځوانۍ ورځې بيا راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_25.mp3', '', 1761754199, 1761754199);